    {
      "design": "r2A",
      "good": "All engineer names and phone numbers stay on one line, making the contact pair easy to scan. The week and role shading establishes a clear hierarchy, and the notes remain readable.",
      "problems": "Every date range breaks across two lines, and two notes need four lines. The extra height leaves substantial empty space in the contact columns.",
      "cause": "The 95px week column cannot hold a full date range, while the 222px notes column forces the longer notes into four lines. The 150px engineer column preserves full names but leaves less space for notes."
    },
    {
      "design": "r2B",
      "good": "The 242px notes column gives the action text more breathing room; five of the six notes fit in three lines. Phone numbers and role labels remain intact, and the rows read clearly across.",
      "problems": "Three engineer names wrap, making the contact column less consistent to scan. All three date ranges also break across lines.",
      "cause": "The 130px engineer column provides 109px of text space, less than some full names need. The 95px week column is too narrow for complete date ranges."
    },
    {
      "design": "r2C",
      "good": "The wider week column keeps the Week 15 and Week 16 date ranges together. Role labels and phone numbers remain intact.",
      "problems": "The Week 14 date still breaks awkwardly before its final day, two engineer names wrap, and several notes are more fragmented. The resulting tall rows spread the contact information farther apart.",
      "cause": "The 120px week column is still too narrow for the longest date range. Its additional width comes largely from the notes column, leaving that column at 212px; the 135px engineer column also cannot hold every full name."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-contacts",
      "widths": [95, 99, 150, 153, 222],
      "change": "Use r2A as the contact-first baseline: full names and phone numbers stay together, while the merged week cells absorb date wrapping. This is included as the comparison point for the alternatives."
    },
    {
      "name": "notes-first",
      "widths": [90, 99, 130, 153, 247],
      "change": "Refine r2B by moving 5px from the week column to notes. The week dates already wrap, so the extra notes space may improve line breaks while keeping roles and phone numbers intact."
    },
    {
      "name": "dates-first",
      "widths": [140, 99, 112, 153, 215],
